"""Conservative density and developmental-moment PDE solver."""

from __future__ import annotations

from dataclasses import dataclass
import math

import numpy as np
import pandas as pd

from .config import SimulationConfig
from .dynamics import neuron_birth_rho, neuron_q, radial_glia_rho, stopping_velocity


@dataclass(frozen=True)
class PDEResult:
    """Truth fields generated by the cortical transport system."""

    z: np.ndarray
    time: np.ndarray
    cohort_table: pd.DataFrame
    velocity_by_cohort: dict[str, np.ndarray]
    density_by_cohort: dict[str, np.ndarray]
    moment_by_cohort: dict[str, np.ndarray]
    rho_by_cohort: dict[str, np.ndarray]
    radial_glia_density: np.ndarray
    radial_glia_rho: np.ndarray
    density_total: np.ndarray
    moment_total: np.ndarray
    rho_observed: np.ndarray
    rho_support_mask: np.ndarray
    explicit_steps: int
    dt_cfl: float
    dz: float


def _normalized_gaussian(
    coordinates: np.ndarray,
    *,
    center: float,
    sigma: float,
) -> np.ndarray:
    values = np.exp(-0.5 * ((coordinates - center) / sigma) ** 2)
    integral = float(np.trapezoid(values, coordinates))
    if integral <= 0.0:
        raise RuntimeError("Gaussian normalization failed.")
    return values / integral


def _gaussian_time_rate(t: float, *, center: float, sigma: float) -> float:
    return float(
        math.exp(-0.5 * ((t - center) / sigma) ** 2)
        / (sigma * math.sqrt(2.0 * math.pi))
    )


def _positive_upwind_flux(
    field: np.ndarray,
    velocity_interfaces: np.ndarray,
) -> np.ndarray:
    flux = np.zeros(len(field) + 1, dtype=float)
    flux[0] = 0.0
    flux[1:-1] = velocity_interfaces[1:-1] * field[:-1]
    flux[-1] = velocity_interfaces[-1] * field[-1]
    return flux


def _advect_source_step(
    field: np.ndarray,
    *,
    velocity_interfaces: np.ndarray,
    source: np.ndarray,
    dt: float,
    dz: float,
) -> np.ndarray:
    flux = _positive_upwind_flux(field, velocity_interfaces)
    updated = field - (dt / dz) * (flux[1:] - flux[:-1]) + dt * source
    return np.maximum(updated, 0.0)


def _cohort_table(config: SimulationConfig) -> pd.DataFrame:
    edges = config.stopping_layer_edges
    return pd.DataFrame(
        {
            "cohort": [f"layer_{index + 1}" for index in range(config.n_timepoints)],
            "birth_time": config.birth_times,
            "stopping_position": config.stopping_points,
            "layer_lower_edge": edges[:-1],
            "layer_upper_edge": edges[1:],
        }
    )


def solve_cortical_pde(config: SimulationConfig) -> PDEResult:
    """Solve cohort density and ``rho``-moment equations at tissue times.

    For cohort ``k`` the solver advances

    ``d_t n_k + d_z(v_k n_k) = b_k``

    and

    ``d_t m_k + d_z(v_k m_k) = b_k rho_birth,k + n_k q_k``,

    where ``m_k=n_k rho_k``. Radial glia are stationary near ``z=0`` and are
    combined with all neuronal cohorts through a density-weighted mean.
    """
    config.validate()

    z = np.linspace(config.z_min, config.z_max, config.n_z)
    dz = float(z[1] - z[0])
    time = config.tissue_times
    cohort_table = _cohort_table(config)

    z_interfaces = np.linspace(
        config.z_min - 0.5 * dz,
        config.z_max + 0.5 * dz,
        config.n_z + 1,
    )
    z_interfaces = np.clip(z_interfaces, config.z_min, config.z_max)

    birth_spatial_profile = _normalized_gaussian(
        z,
        center=config.birth_z_center,
        sigma=config.birth_z_sigma,
    )
    rg_density_profile = config.rg_total_mass * _normalized_gaussian(
        z,
        center=config.rg_z_center,
        sigma=config.rg_z_sigma,
    )

    velocity_centers: dict[str, np.ndarray] = {}
    velocity_interfaces: dict[str, np.ndarray] = {}
    for row in cohort_table.itertuples(index=False):
        velocity_centers[row.cohort] = stopping_velocity(
            z,
            peak_velocity=config.peak_velocity,
            stopping_point=float(row.stopping_position),
            deceleration_width=config.deceleration_width,
        )
        velocity_interfaces[row.cohort] = stopping_velocity(
            z_interfaces,
            peak_velocity=config.peak_velocity,
            stopping_point=float(row.stopping_position),
            deceleration_width=config.deceleration_width,
        )

    maximum_velocity = max(
        float(np.max(np.abs(values))) for values in velocity_interfaces.values()
    )
    if maximum_velocity <= 0.0:
        raise RuntimeError("The neuronal velocity field is identically zero.")
    dt_cfl = config.cfl * dz / maximum_velocity

    density_state = {
        name: np.zeros(config.n_z, dtype=float) for name in cohort_table["cohort"]
    }
    moment_state = {
        name: np.zeros(config.n_z, dtype=float) for name in cohort_table["cohort"]
    }
    density_snapshots = {name: [] for name in cohort_table["cohort"]}
    moment_snapshots = {name: [] for name in cohort_table["cohort"]}

    def save_snapshot() -> None:
        for name in cohort_table["cohort"]:
            density_snapshots[name].append(density_state[name].copy())
            moment_snapshots[name].append(moment_state[name].copy())

    save_snapshot()
    current_time = float(time[0])
    explicit_steps = 0

    for target_time in time[1:]:
        target_time = float(target_time)
        while current_time < target_time - 1e-14:
            dt = min(dt_cfl, target_time - current_time)

            for row in cohort_table.itertuples(index=False):
                name = row.cohort
                birth_time = float(row.birth_time)
                density = density_state[name]
                moment = moment_state[name]

                birth_rate = config.cohort_total_mass * _gaussian_time_rate(
                    current_time,
                    center=birth_time,
                    sigma=config.birth_time_sigma,
                )
                birth_source = birth_rate * birth_spatial_profile
                inherited_rho = neuron_birth_rho(birth_time, config)
                q_value = float(
                    np.asarray(neuron_q(current_time, birth_time=birth_time, config=config))
                )

                density_new = _advect_source_step(
                    density,
                    velocity_interfaces=velocity_interfaces[name],
                    source=birth_source,
                    dt=dt,
                    dz=dz,
                )
                moment_new = _advect_source_step(
                    moment,
                    velocity_interfaces=velocity_interfaces[name],
                    source=birth_source * inherited_rho + density * q_value,
                    dt=dt,
                    dz=dz,
                )
                moment_new = np.minimum(
                    moment_new,
                    config.mature_neuron_rho * density_new + 1e-12,
                )

                density_state[name] = density_new
                moment_state[name] = moment_new

            current_time += dt
            explicit_steps += 1

        current_time = target_time
        save_snapshot()

    density_by_cohort = {
        name: np.asarray(snapshots, dtype=float)
        for name, snapshots in density_snapshots.items()
    }
    moment_by_cohort = {
        name: np.asarray(snapshots, dtype=float)
        for name, snapshots in moment_snapshots.items()
    }
    rho_by_cohort: dict[str, np.ndarray] = {}
    for name in cohort_table["cohort"]:
        density = density_by_cohort[name]
        moment = moment_by_cohort[name]
        rho_by_cohort[name] = np.divide(
            moment,
            density,
            out=np.full_like(moment, np.nan),
            where=density > 1e-12,
        )

    rg_rho_over_time = np.asarray(radial_glia_rho(time, config), dtype=float)
    rg_density_grid = np.broadcast_to(
        rg_density_profile,
        (config.n_timepoints, config.n_z),
    ).copy()
    rg_moment_grid = rg_density_grid * rg_rho_over_time[:, None]

    density_total = rg_density_grid.copy()
    moment_total = rg_moment_grid.copy()
    for name in cohort_table["cohort"]:
        density_total += density_by_cohort[name]
        moment_total += moment_by_cohort[name]

    rho_observed = np.divide(
        moment_total,
        density_total,
        out=np.full_like(moment_total, np.nan),
        where=density_total > 1e-14,
    )
    density_threshold = max(
        1e-14,
        config.density_support_fraction * float(np.max(density_total)),
    )
    rho_support_mask = np.isfinite(rho_observed) & (
        density_total > density_threshold
    )

    return PDEResult(
        z=z,
        time=time,
        cohort_table=cohort_table,
        velocity_by_cohort=velocity_centers,
        density_by_cohort=density_by_cohort,
        moment_by_cohort=moment_by_cohort,
        rho_by_cohort=rho_by_cohort,
        radial_glia_density=rg_density_grid,
        radial_glia_rho=rg_rho_over_time,
        density_total=density_total,
        moment_total=moment_total,
        rho_observed=rho_observed,
        rho_support_mask=rho_support_mask,
        explicit_steps=explicit_steps,
        dt_cfl=dt_cfl,
        dz=dz,
    )
